/* ct_freefactor.c -- THE FREE-FACTOR COLUMN (S1 (p), 2026-11-01 15:3x EST; the trunk seat), included by cut_reader_w.c.  Theorem S12-b
 * needs the subgroup H generated by the boundary words to be a free factor of pi_1(G) = F_r.  Gersten's form of Whitehead's
 * algorithm ("On Whitehead's algorithm", 1984): H is a free factor iff Whitehead automorphisms (type II) reduce the number of edges
 * of its Stallings core graph to a sub-rose (one vertex, each basis letter at most once).  Here: the words' petals are folded to the
 * Stallings graph of H, a basis of H is read from a spanning tree, every type-II automorphism (A, a) is applied to the basis, the
 * images refolded and their core graph's edges counted; an automorphism that lowers the count is applied, until none does.
 * FREE FACTOR iff the final core graph is a sub-rose.  The rank of H is E - V + 1 of the core graph.  Known answers: Object A
 * (H = <U>, a free factor of F_1), Object C (H = <a, b, ab> = F_2, a free factor of itself); the obstruction a b a^-1 b^-1 a
 * (iii-73, 15:3x) is NOT a free factor of F_2 and reads so. */
#define FF_MAXV (CT_MAXW * CT_MAXL + 4)
typedef struct { int u, w, c, alive; } ffedge_t;
static int ffpar[FF_MAXV]; static int ff_fnd(int x) { while (ffpar[x] != x) x = ffpar[x] = ffpar[ffpar[x]]; return x; }
static ffedge_t FFE[FF_MAXV]; static int FFn;
/* build the petal graph of the words, fold it, strip the hairs; returns the core graph's edge count (or -1 on overflow), V in *Vout */
static int ff_fold(int (*wds)[CT_MAXL], const int *lens, int nw, int *Vout, int *rank_out) {
  int nv = 1; FFn = 0;
  for (int b = 0; b < nw; b++) { int L = lens[b]; if (L == 0) continue; int prev = 0;
    for (int k = 0; k < L; k++) { int nxt = (k == L - 1) ? 0 : nv++; if (nv >= FF_MAXV - 1 || FFn >= FF_MAXV - 1) return -1; int let = wds[b][k];
      if (let > 0) { FFE[FFn].u = prev; FFE[FFn].w = nxt; FFE[FFn].c = let; } else { FFE[FFn].u = nxt; FFE[FFn].w = prev; FFE[FFn].c = -let; } FFE[FFn].alive = 1; FFn++; prev = nxt; } }
  for (int v = 0; v < nv; v++) ffpar[v] = v;
  int changed = 1; while (changed) { changed = 0;
    for (int i = 0; i < FFn && !changed; i++) { if (!FFE[i].alive) continue; for (int j = i + 1; j < FFn && !changed; j++) { if (!FFE[j].alive || FFE[j].c != FFE[i].c) continue;
        int ui = ff_fnd(FFE[i].u), uj = ff_fnd(FFE[j].u), wi = ff_fnd(FFE[i].w), wj = ff_fnd(FFE[j].w);
        if (ui == uj) { if (wi != wj) ffpar[wi] = wj; FFE[j].alive = 0; changed = 1; }
        else if (wi == wj) { if (ui != uj) ffpar[ui] = uj; FFE[j].alive = 0; changed = 1; } } } }
  /* canonical vertices; strip hairs (degree-one vertices) repeatedly */
  static int deg[FF_MAXV]; int stripped = 1;
  while (stripped) { stripped = 0; for (int v = 0; v < nv; v++) deg[v] = 0;
    for (int i = 0; i < FFn; i++) if (FFE[i].alive) { deg[ff_fnd(FFE[i].u)]++; deg[ff_fnd(FFE[i].w)]++; }
    for (int i = 0; i < FFn; i++) if (FFE[i].alive) { int u = ff_fnd(FFE[i].u), w = ff_fnd(FFE[i].w); if (deg[u] == 1 || deg[w] == 1) { FFE[i].alive = 0; stripped = 1; } } }
  int V = 0, E = 0; static int seenv[FF_MAXV]; for (int v = 0; v < nv; v++) seenv[v] = 0;
  for (int i = 0; i < FFn; i++) if (FFE[i].alive) { E++; int u = ff_fnd(FFE[i].u), w = ff_fnd(FFE[i].w); if (!seenv[u]) { seenv[u] = 1; V++; } if (!seenv[w]) { seenv[w] = 1; V++; } }
  *Vout = V; *rank_out = (V > 0) ? E - V + 1 : 0; return E; }
/* a basis of H from the folded core graph: a spanning tree by BFS from any vertex, one word per non-tree edge */
static int ff_basis(int (*out)[CT_MAXL], int *outL, int maxw) {
  static int vlist[FF_MAXV], parent_e[FF_MAXV], parent_dir[FF_MAXV], depth[FF_MAXV], inq[FF_MAXV]; int nq = 0, used = 0;
  int root = -1; for (int i = 0; i < FFn; i++) if (FFE[i].alive) { root = ff_fnd(FFE[i].u); break; } if (root < 0) return 0;
  static int mark[FF_MAXV]; for (int i = 0; i < FF_MAXV; i++) { mark[i] = 0; inq[i] = 0; }
  vlist[nq++] = root; inq[root] = 1; parent_e[root] = -1; depth[root] = 0; int head = 0; static int tree[FF_MAXV]; for (int i = 0; i < FFn; i++) tree[i] = 0;
  while (head < nq) { int v = vlist[head++]; for (int i = 0; i < FFn; i++) { if (!FFE[i].alive) continue; int u = ff_fnd(FFE[i].u), w = ff_fnd(FFE[i].w); int other = -1, dir = 0;
      if (u == v && !inq[w]) { other = w; dir = +1; } else if (w == v && !inq[u]) { other = u; dir = -1; }
      if (other >= 0) { inq[other] = 1; parent_e[other] = i; parent_dir[other] = dir; depth[other] = depth[v] + 1; vlist[nq++] = other; tree[i] = 1; } } }
  /* the path word from the root to a vertex: letters along the tree */
  for (int i = 0; i < FFn; i++) { if (!FFE[i].alive || tree[i]) continue; if (used >= maxw) return -1;
    int u = ff_fnd(FFE[i].u), w = ff_fnd(FFE[i].w); static int pu[CT_MAXL], pw[CT_MAXL]; int lu = 0, lw = 0;
    for (int v = u; parent_e[v] >= 0; v = parent_dir[v] > 0 ? ff_fnd(FFE[parent_e[v]].u) : ff_fnd(FFE[parent_e[v]].w)) { if (lu >= CT_MAXL) return -1; pu[lu++] = parent_dir[v] > 0 ? FFE[parent_e[v]].c : -FFE[parent_e[v]].c; }
    for (int v = w; parent_e[v] >= 0; v = parent_dir[v] > 0 ? ff_fnd(FFE[parent_e[v]].u) : ff_fnd(FFE[parent_e[v]].w)) { if (lw >= CT_MAXL) return -1; pw[lw++] = parent_dir[v] > 0 ? FFE[parent_e[v]].c : -FFE[parent_e[v]].c; }
    int m = 0; for (int k = lu - 1; k >= 0; k--) { if (m >= CT_MAXL) return -1; out[used][m++] = pu[k]; }   /* root -> u */
    if (m >= CT_MAXL) return -1; out[used][m++] = FFE[i].c;                                                    /* the edge u -> w */
    for (int k = 0; k < lw; k++) { if (m >= CT_MAXL) return -1; out[used][m++] = -pw[k]; }                     /* w -> root */
    /* free reduction */
    int n = 0; for (int k = 0; k < m; k++) { if (n > 0 && out[used][n - 1] == -out[used][k]) n--; else out[used][n++] = out[used][k]; } outL[used] = n; used++; }
  (void)mark; return used; }
static int ff_apply(int r, int a, unsigned A, int (*src)[CT_MAXL], const int *srcL, int nw, int (*dst)[CT_MAXL], int *dstL) {   /* the type-II automorphism (A, a) on elements, freely reduced */
  for (int b = 0; b < nw; b++) { int m = 0; for (int k = 0; k < srcL[b]; k++) { int x = src[b][k]; int y = x > 0 ? x : -x; int seq[3], ns = 0;
      if (y == (a > 0 ? a : -a)) { seq[ns++] = y; } else { int yinA = (A >> ct_let_idx(y, r)) & 1, yinvA = (A >> ct_let_idx(-y, r)) & 1;
        if (yinA && !yinvA) { seq[ns++] = y; seq[ns++] = a; } else if (!yinA && yinvA) { seq[ns++] = -a; seq[ns++] = y; } else if (yinA && yinvA) { seq[ns++] = -a; seq[ns++] = y; seq[ns++] = a; } else { seq[ns++] = y; } }
      if (x > 0) { for (int i = 0; i < ns; i++) { if (m >= CT_MAXL) return -1; if (m > 0 && dst[b][m - 1] == -seq[i]) m--; else dst[b][m++] = seq[i]; } }
      else { for (int i = ns - 1; i >= 0; i--) { if (m >= CT_MAXL) return -1; if (m > 0 && dst[b][m - 1] == seq[i]) m--; else dst[b][m++] = -seq[i]; } } }
    dstL[b] = m; }
  return 0; }
/* returns 1 (free factor), 0 (not), -1 (overflow); the rank of H and the final core edge count in the outputs */
static int ct_freefactor(int r, int *rank_out, int *edges_out) {
  static int B1[CT_MAXW][CT_MAXL], B2[CT_MAXW][CT_MAXL], B3[CT_MAXW][CT_MAXL]; static int L1[CT_MAXW], L2[CT_MAXW], L3[CT_MAXW];
  int V, rank; int E = ff_fold(WW, WL, NW, &V, &rank); if (E < 0) return -1; *rank_out = rank; if (E == 0) { *edges_out = 0; return 1; }
  int nb = ff_basis(B1, L1, CT_MAXW); if (nb < 0) return -1;
  int improved = 1, rounds = 0; while (improved && rounds++ < 500) { improved = 0;
    for (int ai = 0; ai < 2 * r && !improved; ai++) { int a = ai < r ? ai + 1 : -(ai - r + 1); unsigned nl = 2 * r;
      for (unsigned A = 0; A < (1u << nl) && !improved; A++) { if (!((A >> ct_let_idx(a, r)) & 1)) continue; if ((A >> ct_let_idx(-a, r)) & 1) continue;
        if (ff_apply(r, a, A, B1, L1, nb, B2, L2) < 0) continue; int V2, rk2; int E2 = ff_fold(B2, L2, nb, &V2, &rk2); if (E2 < 0) continue;
        if (E2 < E) { int nb2 = ff_basis(B3, L3, CT_MAXW); if (nb2 < 0) continue; for (int t = 0; t < nb2; t++) { memcpy(B1[t], B3[t], sizeof(int) * L3[t]); L1[t] = L3[t]; } nb = nb2; E = E2; V = V2; improved = 1; } } } }
  *edges_out = E;
  /* a sub-rose: one vertex, each label at most once */
  if (V != 1) return 0; { int seenc[64]; for (int c = 0; c < 64; c++) seenc[c] = 0; for (int i = 0; i < FFn; i++) if (FFE[i].alive) { if (FFE[i].c < 64) { if (seenc[FFE[i].c]) return 0; seenc[FFE[i].c] = 1; } } }
  return 1; }
